1	use std::env;
2	use std::fs;
3	use std::process::ExitCode;
4	
5	fn main() -> ExitCode {
6	    match run() {
7	        Ok(()) => ExitCode::SUCCESS,
8	        Err(Fail::Usage) => {
9	            eprintln!("{}", usage());
10	            ExitCode::from(2)
11	        }
12	        Err(Fail::Read(msg)) => {
13	            eprintln!("chainview: {msg}");
14	            ExitCode::from(2)
15	        }
16	        Err(Fail::Cert(msg)) => {
17	            eprintln!("chainview: invalid DER certificate: {msg}");
18	            ExitCode::from(2)
19	        }
20	        Err(Fail::Output(msg)) => {
21	            eprintln!("chainview: write error: {msg}");
22	            ExitCode::from(2)
23	        }
24	    }
25	}
26	
27	enum Fail {
28	    Usage,
29	    Read(String),
30	    Cert(String),
31	    Output(String),
32	}
33	
34	fn usage() -> &'static str {
35	    "Usage: chainview inspect <DER-FILE>\n       chainview --version"
36	}
37	
38	fn run() -> Result<(), Fail> {
39	    let args: Vec<String> = env::args().skip(1).collect();
40	    match args.first().map(String::as_str) {
41	        Some("--version") if args.len() == 1 => {
42	            use std::io::Write;
43	            std::io::stdout()
44	                .lock()
45	                .write_all(b"chainview 0.1.0\n")
46	                .map_err(|e| Fail::Output(e.to_string()))
47	        }
48	        Some("inspect") => inspect(&args[1..]),
49	        _ => Err(Fail::Usage),
50	    }
51	}
52	
53	fn inspect(args: &[String]) -> Result<(), Fail> {
54	    let path = match args {
55	        [path] if !path.starts_with('-') => path,
56	        _ => return Err(Fail::Usage),
57	    };
58	
59	    let data = fs::read(path).map_err(|e| {
60	        Fail::Read(format!("cannot read certificate file '{path}': {e}"))
61	    })?;
62	
63	    let cert = x509::parse(&data).map_err(Fail::Cert)?;
64	
65	    let mut out = String::new();
66	    out.push_str("Subject: ");
67	    out.push_str(&cert.subject);
68	    out.push('\n');
69	    out.push_str("Issuer: ");
70	    out.push_str(&cert.issuer);
71	    out.push('\n');
72	    out.push_str("Serial Number: ");
73	    out.push_str(&cert.serial_hex);
74	    out.push('\n');
75	    out.push_str("Not Before: ");
76	    out.push_str(&cert.not_before);
77	    out.push('\n');
78	    out.push_str("Not After: ");
79	    out.push_str(&cert.not_after);
80	    out.push('\n');
81	
82	    use std::io::Write;
83	    let mut stdout = std::io::stdout().lock();
84	    stdout
85	        .write_all(out.as_bytes())
86	        .and_then(|_| stdout.flush())
87	        .map_err(|e| Fail::Output(e.to_string()))
88	}
