1	//! End-to-end regression tests for the name (Subject/Issuer) decoding and
2	//! display behavior documented in README.md.
3	//!
4	//! These tests drive the real `chainview` binary so the public contract is
5	//! locked as a whole: the five output lines and their order on success, and
6	//! exit code 2 with empty stdout plus the `chainview: invalid DER
7	//! certificate:` stderr prefix on malformed input. Only name decoding is
8	//! exercised — signature verification, trust and expiry are intentionally out
9	//! of scope.
10	//!
11	//! Certificates are built with the tiny zero-dependency DER constructor at the
12	//! bottom of this file, which lets individual name components (including
13	//! truncated or non-minimal value encodings) be crafted byte for byte.
14	
15	use std::fs;
16	use std::path::PathBuf;
17	use std::process::{Command, Output};
18	use std::sync::atomic::{AtomicU64, Ordering};
19	
20	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
21	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
22	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
23	
24	// ----- Known X.520 attribute OID arcs -------------------------------------
25	
26	const CN: &[u64] = &[2, 5, 4, 3];
27	const O: &[u64] = &[2, 5, 4, 10];
28	const C: &[u64] = &[2, 5, 4, 6];
29	const POSTAL_ADDRESS: &[u64] = &[2, 5, 4, 17];
30	const POSTAL_CODE: &[u64] = &[2, 5, 4, 18];
31	
32	// The spec example: a SEQUENCE containing only UTF8String "abc", with its
33	// complete DER encoding.
34	const POSTAL_ADDRESS_ABC_HEX: &str = "30050C03616263";
35	
36	// ----- Success cases -------------------------------------------------------
37	
38	#[test]
39	fn unknown_oid_uses_dotted_oid_and_full_der_hex() {
40	    // The exact README example: UTF8String "abc" for type 1.2.3.4 must render
41	    // as 1.2.3.4=#0C03616263 — tag, length and content, readable text or not.
42	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], "abc")])]);
43	    let issuer = simple_cn_name("Test CA");
44	    let (out, _cert) = run_inspect("unknown-basic", &build_cert(&subject, &issuer));
45	
46	    assert_success(
47	        &out,
48	        "1.2.3.4=#0C03616263",
49	        "CN=Test CA",
50	    );
51	}
52	
53	#[test]
54	fn unknown_oid_value_preserves_long_form_length() {
55	    // A 128-byte content needs the long-form length 0x81 0x80; the hex must
56	    // carry the original TLV header verbatim instead of collapsing the length
57	    // or emitting only the content bytes.
58	    let long_text = "a".repeat(128);
59	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], &long_text)])]);
60	    let issuer = simple_cn_name("Test CA");
61	    let (out, _cert) = run_inspect("unknown-longlen", &build_cert(&subject, &issuer));
62	
63	    let mut expected_hex = String::from("0C8180");
64	    expected_hex.push_str(&"61".repeat(128));
65	    assert_success(&out, &format!("1.2.3.4=#{expected_hex}"), "CN=Test CA");
66	}
67	
68	#[test]
69	fn unknown_oid_under_2_999_keeps_numeric_arcs() {
70	    // 2.999.* is a legal OID whose first subidentifier (1079) needs multiple
71	    // base-128 bytes (0x88 0x37); it must stay a dotted decimal identifier.
72	    let subject = name(&[rdn(&[atv_utf8(&[2, 999, 1], "x")])]);
73	    let issuer = simple_cn_name("Test CA");
74	    let (out, _cert) = run_inspect("unknown-2999", &build_cert(&subject, &issuer));
75	
76	    assert_success(&out, "2.999.1=#0C0178", "CN=Test CA");
77	}
78	
79	#[test]
80	fn unknown_non_string_value_is_shown_as_full_der_hex() {
81	    // An OCTET STRING value (tag 0x04) is not text at all; the full encoding
82	    // still appears after '#'.
83	    let value = tlv(0x04, &[0x01, 0x02, 0x03]);
84	    let subject = name(&[rdn(&[atv(&[1, 2, 3, 4], &value)])]);
85	    let issuer = simple_cn_name("Test CA");
86	    let (out, _cert) = run_inspect("unknown-octet", &build_cert(&subject, &issuer));
87	
88	    assert_success(&out, "1.2.3.4=#0403010203", "CN=Test CA");
89	}
90	
91	#[test]
92	fn mixed_known_and_unknown_attributes_keep_their_own_forms() {
93	    // Encoded RDN order (display is reversed):
94	    //   SET { C=CN }
95	    //   SET { O=示例公司 }
96	    //   SET { CN=example.com, 1.2.3.4 "abc", 1.2.3.4 "def" }
97	    // The last SET is one multi-valued RDN: joined with '+', never split into
98	    // groups; the repeated unknown attribute appears twice (never merged); the
99	    // adjacent CN stays text; CJK content passes through as raw UTF-8; groups
100	    // are shown in reverse order; '#' is the encoding marker, unescaped.
101	    let subject = name(&[
102	        rdn(&[atv_utf8(C, "CN")]),
103	        rdn(&[atv_utf8(O, "示例公司")]),
104	        rdn(&[
105	            atv_utf8(CN, "example.com"),
106	            atv_utf8(&[1, 2, 3, 4], "abc"),
107	            atv_utf8(&[1, 2, 3, 4], "def"),
108	        ]),
109	    ]);
110	    let issuer = simple_cn_name("Test CA");
111	    let (out, _cert) = run_inspect("mixed", &build_cert(&subject, &issuer));
112	
113	    assert_success(
114	        &out,
115	        "CN=example.com+1.2.3.4=#0C03616263+1.2.3.4=#0C03646566,O=示例公司,C=CN",
116	        "CN=Test CA",
117	    );
118	}
119	
120	#[test]
121	fn subject_and_issuer_render_independently() {
122	    // Each name reflects only its own attributes: distinct OID sets and value
123	    // encodings must never bleed across Subject/Issuer.
124	    let subject = name(&[
125	        rdn(&[atv_utf8(O, "测试")]),
126	        rdn(&[atv_utf8(CN, "subject.example")]),
127	    ]);
128	    let issuer = name(&[rdn(&[
129	        atv_utf8(CN, "Example CA"),
130	        atv_utf8(&[1, 2, 3, 4], "abc"),
131	    ])]);
132	    let (out, _cert) = run_inspect("separate-names", &build_cert(&subject, &issuer));
133	
134	    assert_success(
135	        &out,
136	        "CN=subject.example,O=测试",
137	        "CN=Example CA+1.2.3.4=#0C03616263",
138	    );
139	}
140	
141	#[test]
142	fn known_attribute_with_sequence_value_keeps_short_name_and_shows_der_hex() {
143	    // The exact spec example: postalAddress (2.5.4.17) is a known attribute
144	    // whose value is a SEQUENCE { UTF8String "abc" } rather than a string. It
145	    // must render as postalAddress=#30050C03616263 — tag 0x30, length 0x05
146	    // and content verbatim — instead of rejecting the whole certificate.
147	    let value = seq(&tlv(0x0C, b"abc"));
148	    assert_eq!(hex(&value), POSTAL_ADDRESS_ABC_HEX);
149	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &value)])]);
150	    let issuer = simple_cn_name("Test CA");
151	    let (out, _cert) = run_inspect("known-sequence", &build_cert(&subject, &issuer));
152	
153	    assert_success(&out, "postalAddress=#30050C03616263", "CN=Test CA");
154	}
155	
156	#[test]
157	fn known_non_string_value_applies_to_issuer_as_well() {
158	    // The same rule independently governs the Issuer name.
159	    let subject = simple_cn_name("subject.example");
160	    let issuer = name(&[
161	        rdn(&[atv(POSTAL_ADDRESS, &seq(&tlv(0x0C, b"abc")))]),
162	        rdn(&[atv_utf8(CN, "Test CA")]),
163	    ]);
164	    let (out, _cert) = run_inspect("known-sequence-issuer", &build_cert(&subject, &issuer));
165	
166	    assert_success(&out, "CN=subject.example", "CN=Test CA,postalAddress=#30050C03616263");
167	}
168	
169	#[test]
170	fn known_non_string_value_preserves_long_form_length() {
171	    // A legal long-form length in the value TLV must be carried byte for byte
172	    // after '#', not collapsed and not rebuilt from the parsed content.
173	    let value = tlv(0x04, &vec![0x41u8; 128]); // postalCode as OCTET STRING
174	    let subject = name(&[rdn(&[atv(POSTAL_CODE, &value)])]);
175	    let issuer = simple_cn_name("Test CA");
176	    let (out, _cert) = run_inspect("known-longlen", &build_cert(&subject, &issuer));
177	
178	    let mut expected = String::from("postalCode=#048180");
179	    expected.push_str(&"41".repeat(128));
180	    assert_success(&out, &expected, "CN=Test CA");
181	}
182	
183	#[test]
184	fn text_hex_and_unknown_values_mix_without_splitting_multivalued_rdn() {
185	    // One multi-valued RDN mixes a text value (CN), a known attribute shown as
186	    // hex (postalAddress SEQUENCE) and an unknown attribute shown as hex
187	    // (1.2.3.4). The group stays joined with '+'; a preceding text RDN and a
188	    // repeated text CN in another RDN keep their order after reversal.
189	    let subject = name(&[
190	        rdn(&[atv_utf8(C, "CN")]),
191	        rdn(&[atv_utf8(CN, "one"), atv_utf8(CN, "two")]),
192	        rdn(&[
193	            atv_utf8(CN, "example.com"),
194	            atv(POSTAL_ADDRESS, &seq(&tlv(0x0C, b"abc"))),
195	            atv_utf8(&[1, 2, 3, 4], "abc"),
196	        ]),
197	    ]);
198	    let issuer = simple_cn_name("Test CA");
199	    let (out, _cert) = run_inspect("known-mixed", &build_cert(&subject, &issuer));
200	
201	    assert_success(
202	        &out,
203	        &format!(
204	            "CN=example.com+postalAddress=#{POSTAL_ADDRESS_ABC_HEX}+1.2.3.4=#0C03616263,\
205	             CN=one+CN=two,C=CN"
206	        ),
207	        "CN=Test CA",
208	    );
209	}
