211	#[test]
212	fn known_attribute_with_bad_string_is_still_rejected_not_hexified() {
213	    // A supported string type that fails to decode must never be salvaged by
214	    // the hex fallback: invalid UTF-8 in a known attribute is still corrupt.
215	    let bad_value = tlv(0x0C, &[0xFF, 0xFE]);
216	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &bad_value)])]);
217	    let issuer = simple_cn_name("Test CA");
218	    let (out, _cert) = run_inspect("known-bad-string", &build_cert(&subject, &issuer));
219	
220	    assert_invalid_certificate(&out);
221	}
222	
223	#[test]
224	fn truncated_known_non_string_value_is_rejected() {
225	    // The non-text value's SEQUENCE header announces five content bytes but
226	    // only four follow; hex display must not mask the truncation.
227	    let mut inner = oid(POSTAL_ADDRESS);
228	    inner.extend_from_slice(&[0x30, 0x05, 0x0C, 0x02, 0xAB]); // len 5, 4 present
229	    let subject = name(&[rdn(&[seq(&inner)])]);
230	    let issuer = simple_cn_name("Test CA");
231	    let (out, _cert) = run_inspect("known-truncated", &build_cert(&subject, &issuer));
232	
233	    assert_invalid_certificate(&out);
234	}
