236	#[test]
237	fn known_non_string_value_with_extra_field_is_rejected() {
238	    // Two value TLVs inside one AttributeTypeAndValue stay illegal even when
239	    // the first value would render as hex.
240	    let two_values = concat(&[&seq(&tlv(0x0C, b"abc")), &tlv(0x05, &[])]);
241	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &two_values)])]);
242	    let issuer = simple_cn_name("Test CA");
243	    let (out, _cert) = run_inspect("known-extra-field", &build_cert(&subject, &issuer));
244	
245	    assert_invalid_certificate(&out);
246	}
