248	#[test]
249	fn empty_subject_keeps_empty_field_while_issuer_shows() {
250	    // An empty SEQUENCE is a valid empty name: the Subject line stays empty
251	    // (just "Subject: ") while Issuer renders normally. All five fields keep
252	    // their documented order, and the time fields are UTC regardless of the
253	    // machine zone.
254	    let subject = tlv(0x30, &[]); // Name ::= SEQUENCE {}
255	    let issuer = simple_cn_name("Example CA");
256	    let (out, _cert) = run_inspect("empty-subject", &build_cert(&subject, &issuer));
257	
258	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
259	    assert!(out.stderr.is_empty());
260	    assert_eq!(
261	        lossy(&out.stdout),
262	        format!(
263	            "Subject: \n\
264	             Issuer: CN=Example CA\n\
265	             Serial Number: {FIXED_SERIAL}\n\
266	             Not Before: {FIXED_NOT_BEFORE}\n\
267	             Not After: {FIXED_NOT_AFTER}\n"
268	        )
269	    );
270	}
