286	#[test]
287	fn invalid_utf8_in_known_attribute_value_is_rejected() {
288	    // Same rule for a known short-name attribute: the value cannot be decoded.
289	    let bad_value = tlv(0x0C, &[0xFF]);
290	    let subject = name(&[rdn(&[atv(CN, &bad_value)])]);
291	    let issuer = simple_cn_name("Test CA");
292	    let (out, _cert) = run_inspect("bad-utf8-known", &build_cert(&subject, &issuer));
