297	#[test]
298	fn truncated_attribute_value_is_rejected() {
299	    // The value header announces five content bytes but only three follow;
300	    // the enclosing SET/SEQUENCE lengths stay well-formed so truncation is
301	    // detected at the value itself.
302	    let mut inner = oid(&[1, 2, 3, 4]);
303	    inner.extend_from_slice(&[0x0C, 0x05, 0x61, 0x62, 0x63]); // len 5, 3 present
304	    let subject = name(&[rdn(&[seq(&inner)])]);
305	    let issuer = simple_cn_name("Test CA");
