311	#[test]
312	fn non_minimal_value_length_encoding_is_rejected() {
313	    // A three-byte value encoded as 0x81 0x03 is not valid DER.
314	    let mut inner = oid(&[1, 2, 3, 4]);
315	    inner.extend_from_slice(&[0x0C, 0x81, 0x03, 0x61, 0x62, 0x63]);
316	    let subject = name(&[rdn(&[seq(&inner)])]);
