323	#[test]
324	fn truncated_certificate_file_is_rejected() {
325	    // Bytes cut off the tail of an otherwise valid certificate: malformed
326	    // input, same failure contract.
327	    let subject = simple_cn_name("subject.example");
328	    let issuer = simple_cn_name("Test CA");
