336	// ----- CLI contract: usage, version and unreadable files ------------------
337	
338	#[test]
339	fn version_flag_keeps_its_output() {
340	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
341	        .arg("--version")
342	        .output()
343	        .expect("running chainview");
344	    assert_eq!(out.status.code(), Some(0));
345	    assert!(out.stderr.is_empty());
346	    assert_eq!(lossy(&out.stdout), "chainview 0.1.0\n");
347	}
