349	#[test]
350	fn missing_path_is_a_usage_error() {
351	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
352	        .arg("inspect")
353	        .output()
354	        .expect("running chainview");
355	    assert_eq!(out.status.code(), Some(2));
356	    assert!(out.stdout.is_empty());
357	    assert_eq!(
358	        lossy(&out.stderr),
359	        "Usage: chainview inspect <DER-FILE>\n       chainview --version\n"
360	    );
