#[test]
fn ordering_compares_outer_length_before_value_text() {
    // A shorter member sorts first even when its text value is larger: the
    // unknown attribute (encoding length 15, value "z") precedes CN
    // (encoding length 16, value "a") purely by outer encoding length. A
    // comparison based on decoded value text ('a' < 'z') would reject this
    // legal certificate.
    let subject = name(&[rdn(&[
        atv_utf8(&[1, 2, 3, 4], "z"),
        atv_utf8(CN, "a"),
    ])]);
    let issuer = simple_cn_name("Test CA");
    let (out, _cert) = run_inspect("order-by-length", &build_cert(&subject, &issuer));

    assert_success(
        &out,
        "1.2.3.4=#0C017A+CN=a",
        "CN=Test CA",
    );

    // The reverse encoding is corrupt: length, not text, decides order.
    let subject = name(&[rdn(&[
        atv_utf8(CN, "a"),
        atv_utf8(&[1, 2, 3, 4], "z"),
    ])]);
    let (out, _cert) = run_inspect("order-by-length-bad", &build_cert(&subject, &issuer));
    assert_invalid_certificate(&out);
}

