cd /tmp && cat > mkder.py <<'EOF'
def tlen(n):
    if n < 0x80: return bytes([n])
    b = []
    while n: b.append(n & 0xFF); n >>= 8
    b.reverse()
    return bytes([0x80 | len(b)]) + bytes(b)

def tlv(tag, content):
    return bytes([tag]) + tlen(len(content)) + content

def seq(*parts):
    c = b"".join(parts)
    return tlv(0x30, c)

def setof(*parts):
    c = b"".join(parts)
    return tlv(0x31, c)

def arc(v):
    out = [v % 128]; v //= 128
    while v: out.append(0x80 | (v % 128)); v //= 128
    out.reverse()
    return bytes(out)

def oid(arcs):
    c = arc(arcs[0]*40 + arcs[1])
    for a in arcs[2:]: c += arc(a)
    return tlv(0x06, c)

CN=[2,5,4,3]; O=[2,5,4,10]; C=[2,5,4,6]

def atv_utf8(arcs, text):
    return seq(oid(arcs), tlv(0x0C, text.encode()))

def name(rdns):
    return seq(*rdns)

serial = tlv(0x02, bytes.fromhex("0E8A4C2F9B17D603"))
alg = seq(oid([1,2,840,113549,1,1,11]), tlv(0x05, b""))
validity = seq(tlv(0x17, b"260115093000Z"), tlv(0x17, b"270115093000Z"))
spki = seq(seq(oid([1,2,840,113549,1,1,1]), tlv(0x05,b"")), tlv(0x03, b"\x00\x01\x00"))

def cert(subject, issuer):
    tbs = seq(serial, alg, issuer, validity, subject, spki)
    return seq(tbs, alg, tlv(0x03, b"\x00"))

issuer_ok = name([setof(atv_utf8(CN, "Test CA"))])

# bad subject: O before CN in same SET (OID arc 0x0A > 0x03 -> not DER sorted)
bad_subj = name([setof(atv_utf8(O,"y"), atv_utf8(CN,"x"))])
open("bad_subj.der","wb").write(cert(bad_subj, issuer_ok))

# bad issuer; subject fine
bad_iss = name([setof(atv_utf8(O,"y"), atv_utf8(CN,"x"))])
open("bad_iss.der","wb").write(cert(issuer_ok, bad_iss))

# good subject: CN before O (sorted), plus duplicate identical members
good_subj = name([setof(atv_utf8(C,"CN")),
                  setof(atv_utf8(CN,"x"), atv_utf8(O,"y")),
                  setof(atv_utf8(CN,"d"), atv_utf8(CN,"d"))])
open("good.der","wb").write(cert(good_subj, issuer_ok))

# bad order driven purely by content bytes: same unknown OID, "b" then "a"
bad_content = name([setof(atv_utf8([1,2,3,4],"b"), atv_utf8([1,2,3,4],"a"))])
open("bad_content.der","wb").write(cert(bad_content, issuer_ok))
print("written")
EOF
